import { RuleRef } from '../grammar-graph/rule-ref';
import { isRange, isRuleEnd, UnresolvedRule } from '../grammar-graph/type-guards';
import { RuleChar, RuleCharExclude, RuleType } from '../grammar-graph/types';
import {
  isRuleDefAlt,
  isRuleDefChar,
  isRuleDefCharAlt,
  isRuleDefCharNot,
  isRuleDefCharRngUpper,
  isRuleDefEnd,
  isRuleDefRef,
} from '../rules-builder/type-guards';
import type { InternalRuleDef } from '../rules-builder/types';
import { last } from '../utils/js';

export const makeCharRule = (ruleDef: InternalRuleDef): RuleChar | RuleCharExclude => {
  const value = [...(ruleDef.value as number[])];
  if (isRuleDefCharNot(ruleDef)) {
    return { type: RuleType.CHAR_EXCLUDE, value };
  }
  return { type: RuleType.CHAR, value };
};

export const buildRuleStack = (linearRules: InternalRuleDef[]): UnresolvedRule[][] => {
  let paths: UnresolvedRule[] = [];

