mkdir -p /tmp/parity && cat > /tmp/parity/parity.ts <<'EOF'
import { readFileSync } from 'node:fs';
import GBNF, { GrammarParseError, InputParseError } from '/workspace/ported_implementation/src/index.ts';

const CASES = JSON.parse(readFileSync('/tmp/cases.json', 'utf8'));
const FIXTURE = JSON.parse(
  readFileSync('/workspace/reference_implementation/tests/fixtures/reference.json', 'utf8')
);
const byName = new Map(FIXTURE.map((c: any) => [c.name, c]));
const STACK_OVERFLOW = 'stack-overflow';

const serialize = (rule: any) =>
  rule.type === 'end' ? { type: rule.type } : { type: rule.type, value: rule.value };

const runCase = (c: any) => {
  try {
    let state = GBNF(c.grammar, c.initial ?? '');
    const steps = [[...state].map(serialize)];
    for (const chunk of c.adds ?? []) {
      state = state.add(chunk);
      steps.push([...state].map(serialize));
    }
    return { name: c.name, ok: true, steps, size: state.size, grammar: state.grammar };
  } catch (err: any) {
    if (err instanceof GrammarParseError || err instanceof InputParseError) {
      return { name: c.name, ok: false, error: err.name, message: err.message };
    }
    if (err instanceof RangeError) {
      return { name: c.name, ok: false, error: STACK_OVERFLOW };
    }
    throw err;
  }
};

const normalize = (r: any) =>
  r.error === 'RangeError' || r.error === STACK_OVERFLOW
    ? { name: r.name, ok: false, error: STACK_OVERFLOW }
    : r;

let failed = 0;
for (const c of CASES) {
  const actual = JSON.stringify(normalize(runCase(c)));
  const expected = JSON.stringify(normalize(byName.get(c.name)));
  if (actual !== expected) {
    failed += 1;
    if (failed <= 5) {
      console.log(`FAIL ${c.name}\n  grammar: ${JSON.stringify(c.grammar)}\n  adds: ${JSON.stringify(c.adds)}\n  expected: ${expected}\n  actual:   ${actual}`);
    }
  }
}
console.log(`${CASES.length - failed}/${CASES.length} cases match the recorded reference`);
process.exit(failed ? 1 : 0);
EOF
cd /workspace/ported_implementation && node --experimental-strip-types /tmp/parity/parity.ts 2>&1 | tail -30

