cat > /tmp/parity/edge.ts <<'EOF'
import GBNF, { GrammarParseError, InputParseError, RuleType, isRange } from '/workspace/ported_implementation/src/index.ts';

const show = (label: string, fn: () => unknown) => {
  try { console.log(label, '->', JSON.stringify(fn())); }
  catch (e: any) { console.log(label, '-> throws', e.constructor.name, JSON.stringify(e.message.split('\n')[0])); }
};

// 1. astral characters work in grammars and input
show('astral rules', () => [...GBNF('root ::= "\u{1F600}"')]);
show('astral input', () => [...GBNF('root ::= "\u{1F600}"', '\u{1F600}')]);
show('astral escape', () => [...GBNF('root ::= "\\U0001F600"', '\u{1F600}')]);

// 2. infinite recursion is bounded rather than blowing the stack
show('left recursion', () => [...GBNF('root ::= root')]);
show('empty-matching star', () => [...GBNF('root ::= a*\na ::= "b"?')]);

// 3. missing root symbol
show('no root', () => [...GBNF('foo ::= "a"')]);

// 4. invalid hex escape
show('bad hex', () => [...GBNF('root ::= "\\x"')]);

// misc API surface
const state = GBNF('root ::= "I like green eggs and ham"');
show('size', () => state.size);
show('grammar', () => state.grammar);
show('chained add', () => [...state.add('I li').add('ke gree')]);
show('code point input', () => [...GBNF('root ::= "abc"', [97, 98])]);
show('single code point input', () => [...GBNF('root ::= "abc"', 97)]);
show('RuleType', () => [RuleType.CHAR, RuleType.CHAR_EXCLUDE, RuleType.END]);
show('isRange', () => [isRange([1, 2]), isRange(1)]);
show('errorForMostRecentInput', () => {
  try { GBNF('root ::= "bar"').add('b').add('a').add('z'); }
  catch (e) { if (e instanceof InputParseError) return e.errorForMostRecentInput.split('\n'); }
});
show('deep ref chain (2000 rules)', () => {
  const rules = ['root ::= r0'];
  for (let i = 0; i < 2000; i++) rules.push(`r${i} ::= r${i + 1}`);
  rules.push('r2000 ::= "z"');
  return [...GBNF(rules.join('\n'))];
});
show('instanceof GrammarParseError', () => {
  try { GBNF(''); } catch (e) { return e instanceof GrammarParseError && e instanceof Error; }
});
EOF
timeout 120 node --experimental-transform-types --no-warnings --import /tmp/parity/hook.mjs /tmp/parity/edge.ts

