const name = (i: number) => { let s = ''; let n = i + 1; while (n > 0) { s += 'abcdefghijklmnopqrstuvwxyz'[(n - 1) % 26]; n = Math.floor((n - 1) / 26); } return `r-${s}`; };
const N = 2000;
const rules = [`root ::= ${name(0)}`];
for (let i = 0; i < N; i++) rules.push(`${name(i)} ::= ${name(i + 1)}`);
rules.push(`${name(N)} ::= "z"`);
const state = GBNF(rules.join('\n'), 'z');
console.log(`chain of ${N} rule refs ->`, JSON.stringify([...state]));
EOF
